package dev.thefoolish.generated.anishelf;
import android.content.*;import android.util.Base64;import java.nio.charset.StandardCharsets;import java.util.*;
public final class LibraryActivity extends AppScreen{protected void render(){title("Library");subtitle("Favorites are stored locally and remain available after restart.");Set<String> favs=store.set("favorites");if(favs.isEmpty())body.addView(text("No favorites yet. Add a title from Browse.",14,false));for(String raw:favs){try{String[] x=raw.split("[|]",5);if(x.length<5)continue;String provider=dec(x[0]),id=dec(x[1]),t=dec(x[2]),summary=dec(x[3]);int eps=Integer.parseInt(x[4]);android.widget.Button b=button(t);b.setContentDescription("Open favorite "+t);b.setOnClickListener(v->{Intent i=new Intent(this,DetailActivity.class);i.putExtra("provider",provider);i.putExtra("id",id);i.putExtra("title",t);i.putExtra("summary",summary);i.putExtra("episodes",eps);startActivity(i);});body.addView(b);}catch(Exception ignored){}}nav();}private String dec(String s){return new String(Base64.decode(s,Base64.NO_WRAP|Base64.URL_SAFE),StandardCharsets.UTF_8);}}
